 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    counts = {v: sum(cell == v for row in g for cell in row)
              for v in {cell for row in g for cell in row}}
    background = max(counts, key=counts.get)
    divider = next(r for r, row in enumerate(g)
                   if len(set(row)) == 1 and row[0] != background)
    divider_color = g[divider][0]
    object_color = next(v for v in counts if v not in (background, divider_color))
    object_rows = [r for r in range(h) if object_color in g[r]]
    top, bottom = min(object_rows), max(object_rows)

    # Move the object along the vertical axis until it is next to the divider.
    if bottom < divider:
        shift = divider - 1 - bottom
        marker_row = top + shift - 1
    else:
        shift = divider + 1 - top
        marker_row = bottom + shift + 1

    original = [row[:] for row in g]
    for r in object_rows:
        for c in range(w):
            if original[r][c] == object_color:
                g[r][c] = background
    for r in object_rows:
        nr = r + shift
        for c in range(w):
            if original[r][c] == object_color:
                g[nr][c] = object_color
    if 0 <= marker_row < h:
        g[marker_row] = [8] * w
    return g
